\title{Prompt-guided Disentangled Representation for Action Recognition}





\author{Tianci Wu, Guangming Zhu\thanks{Corresponding Author},  Jiang Lu, Siyuan Wang, Ning Wang, \\\textbf{Nuoye Xiong, Zhang Liang}\\
